"""Read-only post-test interpretation/visual checks; no counterfactual collection or model calls."""
from experiment import *
import numpy as np,imageio.v2 as imageio
from PIL import Image,ImageDraw,ImageFont
def main():
 meta=read(E/'data/_private/evaluation_metadata.json');details=read(E/'results/pair_details.json');rep={r['episode_id']:r for r in details if r['model']=='candidate_seed0'};actual={r['episode_id']:r for r in details if r['model']=='real_next_observation'};errors=[r for r in rep.values()if not r['all7_correct']];oldmeta=read(TRAIN/'data/_private/evaluation_metadata.json');oldy=np.load(TRAIN/'data/_private/targets.npz')['before_y'];support={}
 for split in ['train','dev']:
  ids=[i for i,r in enumerate(oldmeta)if r['split']==split and r['family']=='lift'and oldy[i,:3].sum()==1 and not oldy[i,COLORS.index(r['planned_colour_evaluation_only'])]];support[split]={'held_other_lift_pairs':len(ids),'drawer_open_pairs':int(oldy[ids,6].sum()),'pair_ids':[oldmeta[i]['pair_id']for i in ids]}
 current=[r for r in meta if r['condition']=='held_other_target_table_open'];assert len(current)==12;assert all(not rep[r['episode_id']]['all7_correct']for r in current);support['independent_D']={'held_other_lift_pairs':12,'drawer_open_pairs':12,'candidate_correct':0,'scope':'post-test coverage audit only, no new selection or fit'};save(E/'results/training_support_audit.json',{'created_utc':now(),'source_metadata_sha256':sha(TRAIN/'data/_private/evaluation_metadata.json'),'source_targets_sha256':sha(TRAIN/'data/_private/targets.npz'),'counts':support,'interpretation':'AB/C held-other lift examples all had a closed drawer. Current preregistered D pair uses open drawer. This is a support gap consistent with observed errors, not a controlled demonstration that drawer state alone caused failure; environment/layout also differs.'})
 replacements={'created_utc':now(),'single_replacement':'replace predicted successor latent with already saved actual successor encoding, keep frozen head','candidate_wrong_corrected':sum(not r['all7_correct']and actual[eid]['all7_correct']for eid,r in rep.items()),'candidate_correct_becomes_wrong':sum(r['all7_correct']and not actual[eid]['all7_correct']for eid,r in rep.items()),'both_wrong':sum(not r['all7_correct']and not actual[eid]['all7_correct']for eid,r in rep.items()),'wrong_despite_both_observed_readouts_correct':sum(not r['all7_correct']and r['before_readout_correct']and r['actual_after_readout_correct']for r in rep.values()),'new_inference_or_action_calls':0,'fixes':0,'limitation':'Localizes successor-path failure when endpoint readouts are correct; does not identify representation sufficiency versus transition mapping, or prove the training support gap caused it.'};save(E/'results/replacement_accounting.json',replacements)
 inspected=[]
 for r in errors:
  if r['episode_id'].endswith('__b5'):note='Before/after images show the previously held other-colour block still in gripper, declared target stays on table, drawer open; no successful acquisition of target. Both endpoint readouts correct. Candidate predicts positive target held as well as prior held, creating two UNKNOWN held facts in all12.'
  elif r['episode_id'].endswith('__b2'):note='First error: images show red block held before, pink remains on tabletop; after successful placement red is in open drawer and pink remains on tabletop. Before reader falsely assigns held(pink), alongside held(red), triggering UNKNOWN; successor additionally asserts in(pink) and closed drawer. Earliest observable anomaly is input readout, not proven sole cause.'
  elif r['episode_id'].endswith('__b4'):note='Same initial/prepared observation as first error b2. Refused close leaves red held and drawer open, visible in both endpoint images. Before reader conflicts on held(red)/held(pink); predicted closed drawer is wrong.'
  else:note='Refused placement with closed drawer: images show target block remains in gripper before and after. Candidate loses the held fact. For blue_open_0 b6, actual-after reader additionally falsely assigns in(red) although red visibly remains on tabletop; endpoint readout is also imperfect.'
  inspected.append({'episode_id':r['episode_id'],'error_columns':r['error_columns'],'before_readout_correct':r['before_readout_correct'],'actual_after_readout_correct':r['actual_after_readout_correct'],'visual_observation_and_limits':note,'image':str(E/'figures/cases'/(r['episode_id']+'.png'))})
 save(E/'results/visual_inspection.json',{'created_utc':now(),'completed':True,'all16_candidate_errors_visually_inspected':len(inspected)==16,'inspection_sheets':read(E/'results/inspection_sheets.json'),'first_error_four_input_frames_inspected':str(E/'figures/05_first_input_error.png'),'source':'Assistant inspected actual saved dual-camera triptychs and both 8-case contact sheets through view_image. Visuals corroborate object/gripper/drawer configuration; contact-based labels remain the formal scoring reference.','cases':inspected,'model_changes_or_retests':0})
 videos=read(E/'results/videos.json');audit=[];sheet=Image.new('RGB',(1280,720*len(videos)),'white')
 for j,r in enumerate(videos):
  rr=imageio.get_reader(r['path']);count=rr.count_frames();info=rr.get_meta_data();assert count==r['frames']and abs(info['fps']-30)<1e-6;frame=rr.get_data(count-1);assert frame.shape[:2]==(720,1280);sheet.paste(Image.fromarray(frame),(0,j*720));rr.close();audit.append({'file':r['path'],'decoded_frames':count,'fps':info['fps'],'duration_seconds':info['duration'],'dimensions':[1280,720],'sha256':sha(r['path'])})
 sheet.save(E/'figures/video_final_frames.png');save(E/'results/video_decode_validation.json',{'created_utc':now(),'passed':True,'all_videos_decoded_count_and_final_frame':True,'videos':audit});print(json.dumps({'support':support,'replacement':replacements,'visually_checked_errors':len(inspected),'videos_decoded':len(audit)},ensure_ascii=False),flush=True)
if __name__=='__main__':main()
